"""Network algorithm details and source-backed worked calculations."""
def register(topic, q, detail):
    topic('CUBIC·시간 기반 윈도 함수', '전송 알고리즘', 'net/ipv4/tcp_cubic.c', 'bictcp_update',
     '혼잡 윈도가 증가한다는 설명을 넘어 목표값을 어떤 함수로 계산하는지 알아야 합니다.',
     'CUBIC은 이전 최대 윈도 Wmax 근처에서 W(t)=C(t−K)^3+Wmax 형태의 곡선으로 목표를 계산합니다. K 이전에는 이전 최대에 천천히 접근하고 이후 다시 증가합니다. Linux 구현은 시간 단위와 계수를 정수로 스케일하고 ACK 수에 따른 증가 간격 cnt를 계산합니다.',
     '실제 함수와 설명용 연속 수식의 단위를 구분합니다. beta·friendliness·cwnd 제한·slow start 등이 함께 작동하므로 곡선 하나만으로 전체 전송 상태를 재현했다고 생각하지 않습니다.',
     'bictcp_update의 bic_K·offs·delta·bic_target·cnt와 혼잡 감소 경로를 읽으세요.',
     q('설명용 C=1, K=2, Wmax=10에서 t=3의 목표값은?', '11', '9', '1×(3−2)^3+10=11입니다. 실제 커널은 스케일된 정수 단위를 사용합니다.'),
     q('CUBIC의 cnt가 더 작아지면 일반적으로 어떤 변화인가?', '더 적은 ACK로 윈도 증가를 허용한다', '반드시 모든 전송을 멈춘다', 'cnt는 증가까지 필요한 ACK 누적 간격과 연결됩니다. 실제 코드는 최소값 등 제한을 적용합니다.'),
     details=[detail('최대값 앞뒤의 곡선','t<K면 (t−K)^3가 음수여서 이전 최대 아래에 있습니다. K 근처에서는 기울기가 작아 이전 혼잡 지점을 조심스럽게 탐색합니다. K 이후 증가가 다시 빨라집니다. 이는 매 ACK마다 같은 크기만 증가시키는 단순 선형 규칙과 다릅니다.'),
      detail('커널 정수 계산','코드는 epoch_start 이후 시간을 HZ와 BICTCP_HZ 단위로 변환합니다. |t−K|의 세제곱으로 delta를 만들고 원점에 더하거나 뺍니다. 곱셈 중간값·shift·정수 나눗셈은 단위와 오버플로 범위를 함께 고려합니다.'),
      detail('목표에서 실제 증가로','bic_target−cwnd가 양수면 cwnd와 목표 차이로 cnt를 계산합니다. 목표가 낮으면 작은 증가를 유지하고 friendliness 조정 및 cnt 최소 제한을 수행합니다. 손실 후 감소와 slow start는 별도 경로에서 읽어야 합니다.')])

    topic('BBR·대역폭과 최소 RTT 모델', '전송 알고리즘', 'net/ipv4/tcp_bbr.c', 'bbr_main',
     '손실 횟수만 보는 대신 경로의 전달 속도와 지연으로 전송량을 추정하는 원리를 알아야 합니다.',
     '이 v6.12 구현은 ACK의 전달률 표본으로 최근 대역폭 최대값, RTT 표본으로 최소 RTT를 추정합니다. 대역폭×RTT가 BDP를 나타내고 gain을 적용해 pacing rate와 cwnd를 조절합니다. STARTUP·DRAIN·PROBE_BW·PROBE_RTT 상태를 사용합니다.',
     '평균 RTT와 최소 RTT, rate와 inflight를 구분합니다. 현재 트리의 구현을 미래·다른 BBR 버전과 혼용하지 않습니다. 송신 pacing과 실제 qdisc·환경을 함께 확인합니다.',
     'tcp_bbr.c 첫 설명과 bbr_update_model·bbr_set_pacing_rate·bbr_set_cwnd를 연결하세요.',
     q('설명용 대역폭 100Mbit/s, 최소 RTT 20ms의 BDP는?', '250000바이트', '2000000바이트', '100000000/8×0.020=250000바이트입니다. 비트와 바이트를 먼저 변환합니다.'),
     q('BBR PROBE_RTT가 낮은 inflight를 잠시 사용하는 목적은?', '경로의 최소 지연을 다시 관측한다', '항상 소켓을 영구 종료한다', '큐 영향이 큰 RTT 대신 낮은 inflight에서 경로 지연을 다시 측정하려는 상태입니다.'),
     details=[detail('BDP의 의미','대역폭이 초당 B바이트이고 왕복 시간이 R초면 B×R바이트가 한 RTT 동안 전달될 수 있는 양입니다. pacing rate는 시간당 송신 속도이고 cwnd는 진행 중인 양의 제한입니다. 두 값은 단위부터 다릅니다.'),
      detail('상태 전환','STARTUP은 용량을 탐색하며 속도를 올리고 DRAIN은 쌓인 큐를 줄입니다. 정상 구간에서는 PROBE_BW로 대역폭을 탐색하고 필요 시 PROBE_RTT로 최소 RTT를 갱신합니다. 상태·gain·표본 필터가 결합되어 동작합니다.'),
      detail('관측의 제약','ACK 전달률과 RTT에는 표본 조건·application-limited 상태·네트워크 변화가 영향을 줍니다. 첫 파일 주석의 필터 기간과 구현을 확인해야 하며 BBR이라는 이름만으로 모든 환경의 낮은 지연·공정성이 보장되지는 않습니다.')])

    topic('TCP SACK·손실 구간 식별', '전송 알고리즘', 'net/ipv4/tcp_input.c', 'tcp_sacktag_write_queue',
     '누적 ACK 뒤에도 일부 뒤쪽 데이터가 도착했다는 정보를 송신자가 알 수 있어야 합니다.',
     '누적 ACK는 앞에서부터 연속 수신한 경계입니다. SACK은 그 뒤 수신한 별도 바이트 구간을 알려 송신 큐에서 받은 구간과 빈 구간을 구분하게 합니다. 협상·구간 검증·재정렬·중복 SACK 처리가 필요하며 SACK 정보만으로 모든 재전송 정책이 결정되지는 않습니다.',
     'SACK 구간은 시작 포함·끝 제외의 시퀀스 범위로 읽습니다. 일반 정수 대소 비교 대신 TCP 시퀀스의 래핑 규칙을 고려합니다.',
     'tcp_sacktag_write_queue의 구간 파싱·검증과 tcp_check_dsack를 읽으세요.',
     q('누적 ACK 500, SACK [1000,1500)이면 아직 연속 수신에 빈 앞 구간은?', '[500,1000)', '[1000,1500)', '뒤 구간은 수신했지만 ACK 500부터 1000까지의 구간이 연속 수신 경계를 막고 있습니다.'),
     q('SACK [1000,1500)이 나타내는 바이트 수는?', '500바이트', '501바이트', '끝을 제외하므로 1500−1000=500입니다. 포함 끝점 구간과 구분합니다.'),
     details=[detail('송신 큐의 표식','송신 큐의 sk_buff는 보낸 바이트 범위를 나타냅니다. SACK 구간과 겹치는 항목에 수신 표식을 붙이며 이미 받은 양과 재전송할 후보를 구분합니다. 하나의 패킷 객체와 바이트 구간이 항상 일대일이라고 가정하지 않습니다.'),
      detail('입력 검증','SACK option 길이·구간 수·시퀀스 유효 범위를 확인합니다. 과거 ACK를 다루는 조건과 중복 수신 정보 DSACK를 구분합니다. 네트워크 입력을 그대로 신뢰하지 않는 검사도 알고리즘의 일부입니다.'),
      detail('누적 ACK를 대체하지 않기','SACK은 추가 수신 정보이며 누적 ACK의 기본 의미를 없애지 않습니다. 수신자의 버퍼·송신자의 scoreboard와 손실 복구 정책을 연결해서 읽어야 실제 재전송 판단을 이해할 수 있습니다.')])

    topic('ECN·드롭 대신 혼잡 알림', '전송 알고리즘', 'net/ipv4/tcp_input.c', 'tcp_ecn_check_ce',
     '혼잡을 알리기 위해 항상 패킷을 버리지 않고 명시적 표시를 전달할 수 있습니다.',
     'ECN 지원을 협상한 전송과 네트워크가 ECT·CE 등의 표시를 사용합니다. TCP 수신자는 CE를 관찰해 피드백을 전달하고 송신자가 혼잡 제어에 반영합니다. IP의 혼잡 표시와 TCP의 ECE·CWR 역할을 구분합니다.',
     '전송·큐·경로의 지원 상태를 함께 확인합니다. ECN이 활성이라고 손실이 절대 없거나 모든 라우터가 항상 표시하는 것은 아닙니다.',
     'tcp_ecn_check_ce와 __tcp_ecn_check_ce의 CE 분기·DEMAND_CWR 표식을 읽으세요.',
     q('ECN CE는 어떤 정보를 전달하는가?', '혼잡이 관측되었다는 표시', '항상 데이터 복호화 성공', 'Congestion Experienced는 네트워크 혼잡 신호입니다.'),
     q('ECN을 사용하면 모든 패킷 손실이 불가능해지는가?', '아니다', '항상 불가능하다', '표시를 통한 제어를 지원해도 큐 초과·오류·지원 조건 등으로 손실이 있을 수 있습니다.'),
     details=[detail('표시의 전달 경로','송신 측이 ECN 가능한 패킷을 만들고 경로가 혼잡 시 CE를 표시할 수 있습니다. 수신 측이 TCP 피드백을 만들고 송신 측이 혼잡 반응을 수행합니다. IP 필드와 TCP 플래그를 한 개의 동일 값처럼 취급하지 않습니다.'),
      detail('협상과 처리 조건','tcp_ecn_check_ce는 해당 소켓의 ECN 상태를 먼저 검사합니다. 내부 함수는 IP dsfield의 ECN 비트에 따라 분기하고 ACK 처리와 혼잡 이벤트를 연결합니다. 표식을 읽는 것과 실제 윈도·rate 조절은 별도의 코드입니다.'),
      detail('실제 적용','큐 discipline의 ECN 기능과 TCP 설정·혼잡 제어·원격 지원을 확인합니다. 드롭 수만 보지 말고 CE 표시와 응답 지연도 함께 관측해야 혼잡 제어 동작을 이해할 수 있습니다.')])

    topic('IPv6·주소와 확장 헤더', '네트워크', 'net/ipv6/exthdrs.c', 'ipv6_parse_hopopts',
     'IPv4와 다른 주소 공간·헤더 구조를 가진 패킷을 길이와 옵션 규약에 맞춰 해석해야 합니다.',
     'IPv6 주소는 128비트이며 기본 헤더 다음에 next-header로 이어지는 확장 헤더가 올 수 있습니다. 옵션은 길이·형식·처리 규칙을 검증합니다. Hop-by-Hop 옵션의 길이 계산과 정책 제한은 무한한 옵션 파싱을 허용하지 않습니다.',
     '헤더의 next-header·길이를 확인하고 IPv4와 다른 주소·이웃 발견 체계를 구분합니다. 패킷에 선언된 길이만 믿지 말고 실제 버퍼의 접근 가능한 범위를 확인합니다.',
     'ipv6_parse_hopopts의 pskb_may_pull·extlen·max_hbh_opts_len·ip6_parse_tlv를 읽으세요.',
     q('Hop-by-Hop 길이 필드가 1이면 이 코드의 헤더 바이트 수는?', '16바이트', '1바이트', 'extlen=(필드+1)×8이므로 (1+1)×8=16바이트입니다.'),
     q('IPv6의 /64에서 주소 전체 128비트 중 접두사 외 비트 수는?', '64비트', '128비트', '128−64=64이며 이는 실제로 모든 주소를 호스트에 할당한다는 뜻은 아닙니다.'),
     details=[detail('길이 검증 순서','기본 필요한 바이트와 선언된 전체 옵션 길이가 버퍼에서 읽힐 수 있는지 확인합니다. 그 뒤 정책의 최대 길이·개수를 적용하고 TLV를 처리합니다. 접근 가능성 검사 전에 옵션 값을 임의 역참조하지 않습니다.'),
      detail('Next Header 체인','기본 헤더의 next-header가 다음 확장 헤더 또는 상위 프로토콜을 지정하고 확장 헤더가 다시 다음 종류를 가리킵니다. TCP 헤더가 항상 기본 헤더 바로 다음에 있다고 가정하면 잘못된 위치를 읽을 수 있습니다.'),
      detail('주소와 프로토콜의 경계','128비트 주소와 접두사 길이는 경로·인터페이스 설정에 사용합니다. IPv6라고 자동 암호화되거나 TCP의 신뢰성 규칙이 달라지는 것은 아닙니다. 네트워크 계층과 전송 계층의 역할을 구분합니다.')])

    topic('WireGuard·터널과 핸드셰이크', '네트워크', 'drivers/net/wireguard/noise.c', 'wg_noise_handshake_create_initiation',
     '네트워크 터널에서 상대의 키와 연결하고 세션별 보호 키를 안전하게 준비해야 합니다.',
     'WireGuard의 Noise 기반 핸드셰이크는 정적·일회성 키, DH 계산, chaining key와 transcript hash를 결합합니다. 암호화된 신원·타임스탬프와 후속 세션 키 처리가 관련됩니다. UDP 터널 데이터 전달과 키 교환은 다른 단계입니다.',
     '검토된 구현의 키·peer·라우팅 규약을 사용합니다. 일반 자료구조 설명용 코드로 핸드셰이크를 대체하지 않습니다. 허용된 IP 설정·peer 선택과 암호학적 인증을 함께 이해합니다.',
     'handshake_init·message_ephemeral·mix_dh·message_encrypt와 initiation 생성 흐름을 읽으세요.',
     q('WireGuard 일회성 키와 정적 신원 키는 같은 수명인가?', '용도와 수명이 다르다', '항상 같은 수명이다', '일회성 키 교환과 장기 peer 신원을 구분해 세션 키를 구성합니다.'),
     q('소스가 난수 준비를 잠금 전에 기다리는 이유는?', '난수 준비 대기와 잠금 문맥을 맞춘다', '항상 암호화가 필요 없어서다', '해당 주석은 키 생성이 난수 준비를 기다릴 수 있으므로 잠금 전 대기를 수행한다고 설명합니다.'),
     details=[detail('키 교환의 흐름','일회성 비밀 키를 만들고 공개 키를 전달합니다. DH 결과를 chaining key에 섞으며 transcript hash와 함께 메시지를 인증·보호합니다. 서로 다른 키 재료와 해시 상태를 같은 변수의 임의 값으로 취급하지 않습니다.'),
      detail('초기화와 실패 경로','CRNG 준비 뒤 신원과 handshake 잠금을 얻고 identity 존재를 검사합니다. 공개 키 생성·DH 실패는 out 경로로 정리합니다. 정상 암호 계산뿐 아니라 잠금·민감한 임시 키·실패 상태 처리도 읽어야 합니다.'),
      detail('터널 사용의 범위','암호학적으로 peer와 연결하더라도 실제 트래픽이 어떤 peer·인터페이스로 가는지는 터널 설정과 라우팅 규약에 달려 있습니다. 터널의 암호화와 전체 호스트의 애플리케이션 권한 정책은 별도입니다.')])

    topic('MPTCP·여러 경로와 시퀀스 공간', '네트워크', 'net/mptcp/protocol.c', 'mptcp_sendmsg',
     '하나의 애플리케이션 스트림을 여러 TCP 경로에서 전송하고 재조립할 수 있어야 합니다.',
     'MPTCP는 전체 연결의 데이터 시퀀스와 각 TCP subflow의 시퀀스를 매핑합니다. 여러 경로의 지연·손실이 달라도 하나의 순서 있는 스트림으로 전달합니다. 경로 관리·스케줄링·재전송·일반 TCP fallback이 관련됩니다.',
     '커널 지원·원격 지원·주소·경로 정책을 확인합니다. 인터페이스가 두 개라는 사실만으로 항상 두 배 처리량이 나오거나 자동 MPTCP가 되는 것은 아닙니다.',
     'mptcp_sendmsg와 데이터 매핑·subflow 선택, fallback 경로를 함께 읽으세요.',
     q('MPTCP 전체 데이터 번호와 subflow TCP 번호는 항상 같은 공간인가?', '매핑되는 별도 시퀀스 공간이다', '항상 같은 공간이다', '여러 TCP 경로의 바이트를 전체 연결의 순서에 연결해야 합니다.'),
     q('네트워크 경로 두 개가 있으면 항상 처리량이 정확히 두 배인가?', '아니다', '항상 두 배다', '대역폭 공유·지연·스케줄링·지원·손실 조건 등이 실제 성능에 영향을 줍니다.'),
     details=[detail('재조립의 필요','빠른 경로의 뒤 데이터가 느린 경로의 앞 데이터보다 먼저 도착할 수 있습니다. 전체 데이터 번호로 재조립하고 앱에는 순서 있는 스트림을 전달합니다. 각 subflow의 TCP 재정렬만으로 전체 스트림의 순서가 자동 해결되지는 않습니다.'),
      detail('스케줄링과 fallback','전송할 데이터·각 경로의 상태·윈도를 고려해 subflow를 선택합니다. 협상·옵션·환경 조건이 충족되지 않으면 일반 TCP 방식으로 fallback할 수 있습니다. MPTCP 객체와 TCP subflow 객체를 구분합니다.'),
      detail('사용과 관찰','관련 커널 설정·MPTCP socket 선택·peer 지원·endpoint 정책을 확인합니다. 각 경로의 성능을 개별로 봐야 병목과 재정렬 비용을 이해할 수 있습니다. 같은 네트워크 병목을 공유하는 경로는 독립 대역폭이 아닐 수 있습니다.')])

    topic('QUIC·커널 UDP와 사용자 공간 프로토콜의 경계', '네트워크', 'net/ipv4/udp.c', 'udp_sendmsg',
     '웹 프로토콜이 UDP를 사용한다는 사실과 Linux 커널이 그 프로토콜 전체를 구현한다는 사실을 구분해야 합니다.',
     '일반적인 QUIC 구현은 사용자 공간에서 신뢰성·여러 스트림·혼잡 제어·암호 핸드셰이크를 구현하고 커널 UDP API를 이용합니다. 이 v6.12 UDP 송신 코드는 데이터그램 전달을 담당하며 QUIC의 전체 상태 머신을 대신하지 않습니다.',
     '해당 라이브러리의 QUIC 상태와 커널 소켓·UDP 큐·네트워크 경로를 따로 관찰합니다. UDP를 선택했다는 사실만으로 전송 신뢰성이나 암호화가 사라지는 것은 아닙니다.',
     'udp_sendmsg의 데이터그램 처리와 사용자 공간 QUIC 라이브러리가 맡을 기능을 구분해 적으세요.',
     q('사용자 공간 QUIC의 재전송을 이 UDP 함수가 자동으로 전부 구현하는가?', '아니다. 프로토콜 구현의 경계를 구분한다', '항상 전부 구현한다', '커널 UDP와 사용자 공간 상위 프로토콜은 역할이 다릅니다.'),
     q('UDP 기반이면 애플리케이션 프로토콜이 신뢰성을 구현할 수 없는가?', '상위 계층에서 구현할 수 있다', '절대로 구현할 수 없다', '하위 서비스의 보장과 상위 프로토콜이 구성하는 보장을 구분해야 합니다.'),
     details=[detail('기능 위치를 그려보기','사용자 공간은 스트림·연결 상태·암호·혼잡 정책을 관리하고 UDP socket으로 패킷을 주고받습니다. 커널은 소켓 큐·IP 라우팅·장치 전송 등을 수행합니다. 시스템 콜 추적만으로 사용자 공간 내부 상태를 모두 볼 수는 없습니다.'),
      detail('UDP와 TCP 비교','TCP는 커널이 바이트 스트림의 재전송·순서를 처리하는 일반 경로입니다. QUIC은 UDP 데이터그램 위에 상위 상태를 구성합니다. UDP를 TCP처럼 이어 읽거나 데이터그램 경계를 임의로 무시하지 않습니다.'),
      detail('수업의 원본 범위','이 발췌는 QUIC 자체의 소스가 아니라 Linux UDP 경계의 실제 코드입니다. Linux 내부 기술을 공부할 때도 어디부터 외부 라이브러리 책임인지 밝히는 것이 필요합니다. QUIC RFC 전체를 이 코드의 알고리즘이라고 표시하지 않습니다.')])

    topic('TCP Reno·AIMD의 계산', '전송 알고리즘', 'net/ipv4/tcp_cong.c', 'tcp_reno_cong_avoid',
     '단순한 혼잡 제어부터 증가·감소량을 계산하면 더 복잡한 모듈을 이해하기 쉬워집니다.',
     'Reno는 slow start와 혼잡 회피를 구분합니다. 혼잡 회피의 additive increase와 혼잡 시 multiplicative decrease가 AIMD의 기본 형태입니다. 이 구현의 ssthresh는 cwnd 절반과 최소 2를 고려하며 모든 상태의 실제 cwnd가 항상 즉시 절반이 되는 것은 아닙니다.',
     'cwnd·ssthresh·ACK 수의 단위를 구분하고 제한·slow start·회복 경로를 함께 읽습니다. 이 기본 모듈이 모든 소켓의 기본 정책이라고 가정하지 않습니다.',
     'tcp_reno_cong_avoid·tcp_cong_avoid_ai·tcp_reno_ssthresh를 이어 읽으세요.',
     q('이 구현의 Reno ssthresh에서 cwnd=20이면 새 threshold는?', '10', '40', 'max(cwnd>>1,2)이므로 max(10,2)=10입니다.'),
     q('같은 threshold 규칙에서 cwnd=3이면?', '2', '1', '정수 절반은 1이지만 최소값 2가 적용되어 결과는 2입니다.'),
     details=[detail('Slow Start와 혼잡 회피','slow start는 threshold 아래에서 ACK로 더 빠르게 증가합니다. 혼잡 회피는 누적 ACK 수를 사용해 대략 RTT마다 작은 증가를 만들며 tcp_cong_avoid_ai로 연결됩니다. 윈도가 실제로 전송을 제한하는지 검사하는 조건도 있습니다.'),
      detail('Threshold와 현재 윈도','tcp_reno_ssthresh가 반환하는 값은 이후 동작을 위한 threshold입니다. 현재 cwnd 갱신·손실 회복·undo는 다른 함수에서 처리합니다. 함수 하나의 반환값을 전체 상태 전이와 동일하게 해석하지 않습니다.'),
      detail('AIMD의 목적과 제약','대역폭을 조금씩 탐색하고 혼잡 시 사용량을 줄여 공유 경로에서 반응합니다. 모든 네트워크에 최적의 성능을 보장하는 공식은 아니며 RTT·손실·ACK·다른 흐름의 영향을 봐야 합니다.')])
